arguments.content:
body { font-family: system-ui, sans-serif; margin: 0; }
header, footer { padding: 1rem; background: #f3f4f6; }
.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr)); gap: 1rem; padding: 1rem; }
.card { border: 1px solid #e5e7eb; border-radius: 8px; padding: 1rem; }

fetch('products.json')
  .then((response) => response.json())
  .then((products) => {
    const list = document.getElementById('products');
    for (const product of products) {
      const card = document.createElement('div');
      card.className = 'card';
      card.innerHTML = `<h2>${product.name}</h2><p>$${product.price}</p><button>Buy</button>`;
      card.querySelector('button').addEventListener('click', () => alert(product.name));
      list.appendChild(card);
    }
  });
